function Scoper({ onDone }: { onDone: () => void }) {
  const [message, setMessage] = useState("");
  const [sent, setSent] = useState(false);
  return <div className="scoper"><div className="hero"><div><p className="eyebrow">AI scoper</p><h1>Let’s understand the job</h1><p className="subtitle">A few quick questions help us send a clearer brief to trusted pros.</p></div><button className="secondary" onClick={onDone}>Use guided wizard</button></div><section className="card scoper-window"><div className="scoper-top"><div className="pro-line"><div className="pro-avatar"><Icon name="spark" size={17} /></div><div><h3 style={{ margin: 0 }}>TradeLink AI</h3><div className="job-meta">Usually replies instantly</div></div></div><span className="status open">● Online</span></div><div className="chat-body"><div className="bubble ai">Hi Alex — describe what’s going on in your own words. For example: <strong>“my kitchen sink is leaking under the cabinet.”</strong></div>{sent && <div className="bubble user">{message}</div>}<div className="bubble ai">Thanks, I’ve got it. Is the water leak constant, or does it happen when the tap is running?</div>{sent && <><div className="bubble user">It happens when the tap is running. It’s a standard kitchen sink in a condo.</div><div className="bubble ai"><strong>Here’s what I understand.</strong> You need a kitchen faucet or supply connection checked and repaired. I’ll flag this as a normal-priority plumbing visit and share your photos with nearby pros.</div><div className="spec-grid"><div className="spec-item"><div className="spec-label">Service type</div><div className="spec-value">Kitchen plumbing repair</div></div><div className="spec-item"><div className="spec-label">Urgency</div><div className="spec-value">Within a week</div></div><div className="spec-item"><div className="spec-label">Property</div><div className="spec-value">Condo · Kitchen</div></div><div className="spec-item"><div className="spec-label">Access notes</div><div className="spec-value">Under-sink cabinet</div></div></div><div className="estimate"><div><span>Indicative estimate</span><strong>$180–$320 CAD</strong><span>Typical duration · 1–2 hours</span></div><button className="primary" onClick={onDone}>Confirm job spec <Icon name="arrow" size={14} /></button></div></>}</div><div className="chat-input"><input value={message} onChange={(e) => setMessage(e.target.value)} placeholder="Describe your home repair…" onKeyDown={(e) => { if (e.key === "Enter") setSent(true); }} /><button className="primary" onClick={() => setSent(true)} aria-label="Send message"><Icon name="arrow" size={16} /></button></div></section></div>;
}

