export default function Page() {
  const [role, setRole] = useState<Role>("Customer");
  const [customerView, setCustomerView] = useState<CustomerView>("Home");
  const [proView, setProView] = useState<ProView>("Leads");
  const [adminView, setAdminView] = useState<AdminView>("Overview");
  const [showQuotes, setShowQuotes] = useState(false);
  const nav = role === "Customer" ? ["Home", "My Jobs", "Post", "Inbox", "Profile"] : role === "Pro" ? ["Leads", "Quotes", "Jobs", "Earnings", "Profile"] : ["Overview", "Verification", "Marketplace", "Payments", "Catalog"];
  const current = role === "Customer" ? customerView : role === "Pro" ? proView : adminView;
  const displayTitle = useMemo(() => role === "Admin" ? "TradeLink Admin" : role === "Pro" ? "Pro workspace" : "TradeLink", [role]);
  const setCurrent = (item: string) => { if (role === "Customer") setCustomerView(item as CustomerView); else if (role === "Pro") setProView(item as ProView); else setAdminView(item as AdminView); };
  const render = () => { if (role === "Customer") { if (showQuotes) return <QuotesView onHire={() => { setShowQuotes(false); setCustomerView("My Jobs"); }} />; if (customerView === "Home") return <CustomerHome setView={setCustomerView} />; if (customerView === "Post") return <Scoper onDone={() => setShowQuotes(true)} />; if (customerView === "My Jobs") return <CustomerJobs setView={(view) => view === "Inbox" ? setShowQuotes(true) : setCustomerView(view)} />; return <><div className="hero"><div><p className="eyebrow">{customerView}</p><h1>{customerView === "Inbox" ? "Your conversations" : "Your TradeLink profile"}</h1><p className="subtitle">{customerView === "Inbox" ? "Chat unlocks after you hire a pro. Your kitchen sink repair is ready for a schedule." : "Keep your details and preferences up to date."}</p></div></div><div className="card card-pad"><div className="notice"><Icon name="chat" size={14} /> {customerView === "Inbox" ? "Northline Plumbing · Deposit paid · Choose a visit time to unlock chat." : "Alex Morgan · alex@example.com · Toronto, ON"}</div></div></>; } if (role === "Pro") return <ProView view={proView} setView={setProView} />; return <AdminView view={adminView} />; };
  return <div className="app-shell"><aside className="sidebar"><div className="brand"><span className="brand-mark"><Icon name="arrow" size={17} /></span>TradeLink</div><div className="role-chip"><span>Viewing as</span><strong>{role}</strong></div><nav className="nav" aria-label="Primary navigation">{nav.map((item) => <button key={item} className={current === item ? "active" : ""} onClick={() => { setCurrent(item); setShowQuotes(false); }}><Icon name={navIcons[item]} size={16} />{item}{item === "Inbox" && <span style={{ marginLeft: "auto", background: "var(--blue)", color: "#fff", borderRadius: 99, padding: "2px 6px", fontSize: 9 }}>2</span>}</button>)}</nav><div className="sidebar-footer">Plumbing marketplace<br />Toronto region · CAD<br /><br />© 2025 TradeLink</div></aside><main className="main"><header className="topbar"><div className="topbar-title">{displayTitle}</div><div className="topbar-actions"><button className="icon-button" aria-label="Notifications"><Icon name="bell" size={17} /></button><button className="role-chip desktop-only" style={{ margin: 0, color: "var(--navy)", background: "#fff", borderColor: "var(--line)", gap: 10 }} onClick={() => setRole(role === "Customer" ? "Pro" : role === "Pro" ? "Admin" : "Customer")}><span>Switch role</span><strong>{role === "Customer" ? "Pro" : role === "Pro" ? "Admin" : "Customer"}</strong></button><div className="user-avatar">AM</div></div></header><div className="content">{render()}</div></main><nav className="mobile-tabs" aria-label="Mobile navigation">{nav.slice(0, 5).map((item) => <button key={item} className={current === item ? "active" : ""} onClick={() => { setCurrent(item); setShowQuotes(false); }}><Icon name={navIcons[item]} size={17} />{item}</button>)}</nav></div>;
}
